export const TUBE_SIZE_ROWS: readonly TubeSizeRow[] = TUBE_SIZES_TABLE.sizes
export const END_CONNECTION_TYPES: readonly EndConnectionType[] = END_CONNECTIONS_TABLE.types
  .slice()
  .sort((x, y) => x.sort - y.sort)
export const END_CONNECTION_ROWS: readonly EndConnectionRow[] = END_CONNECTIONS_TABLE.rows
