/** Throws on an unknown size code. */
export function tubeSize(code: SizeCode): TubeSizeRow {
  const row = TUBE_SIZE_ROWS.find((r) => r.size_code === code)
  if (!row) throw new Error(`Unknown tube size code: ${code}`)
  return row
}

/** Tube OD, wall and ID (in). */
export function tubeDims(code: SizeCode): { od: number; wall: number; id: number; label: string } {
  const t = tubeSize(code)
  return { od: t.od_in, wall: t.wall_in, id: t.od_in - 2 * t.wall_in, label: t.label }
}

/** Throws on an unknown code. */
export function endConnectionType(code: EndConnectionCode): EndConnectionType {
  const t = END_CONNECTION_TYPES.find((r) => r.code === code)
  if (!t) throw new Error(`Unknown End Connection code: ${code}`)
  return t
}

/** End Connection type by its Part Number token ("clmp" → tc), or null. */
export function endConnectionTypeByToken(token: string): EndConnectionType | null {
  return END_CONNECTION_TYPES.find((r) => r.pn_token === token) ?? null
}

/** Throws when the table has no row for this code × size. */
export function endConnectionRow(code: EndConnectionCode, size: SizeCode): EndConnectionRow {
  const row = END_CONNECTION_ROWS.find((r) => r.code === code && r.size_code === size)
  if (!row) throw new Error(`No End Connection row for ${code} × ${size}`)
  return row
}

export function hasEndConnectionRow(code: EndConnectionCode, size: SizeCode): boolean {
  return END_CONNECTION_ROWS.some((r) => r.code === code && r.size_code === size)
}

/** Throws on an unknown alloy. */
export function alloyRow(value: AlloyValue): AlloyRow {
  const row = ALLOY_ROWS.find((r) => r.value === value)
  if (!row) throw new Error(`Unknown alloy: ${value}`)
  return row
}

/** Query value ("t316l") → table alloy ("T316L"). */
export function alloyOf(key: AlloyKey): AlloyRow {
  return alloyRow(key === "t304l" ? "T304L" : "T316L")
}

/** Throws on an unknown role. */
export function bomRole(role: string): BomRoleTemplate {
  const r = BOM_ROLES.find((x) => x.role === role)
  if (!r) throw new Error(`Unknown BOM role: ${role}`)
  return r
}

/** Concentric reducer length for the larger size (B16.9 approx). Throws on an unknown size. */
export function reducerLength(largerSize: SizeCode): number {
  const r = ASSEMBLIES.reducers.find((x) => x.size_code === largerSize)
  if (!r) throw new Error(`No reducer length for size ${largerSize}`)
  return r.length_in
}

/** Valve envelope; null when the table has no row (size not offered). */
export function valveRow(kind: "bv" | "bfv", size: SizeCode): { length_in: number; mass_lb: number } | null {
  return ASSEMBLIES.valves.find((v) => v.kind === kind && v.size_code === size) ?? null
}

/** Approximate heavy-duty clamp mass (lb) at a tube size. */
export function clampMassLb(size: SizeCode): number {
  const c = ASSEMBLIES.components
  return c.clamp_mass_lb_base + c.clamp_mass_lb_per_in_od * tubeSize(size).od_in
}

/** Mass (lb) of a tube length. */
export function tubeMassLb(size: SizeCode, lengthIn: number, density: number): number {
  const t = tubeDims(size)
  return (Math.PI / 4) * (t.od * t.od - t.id * t.id) * Math.max(0, lengthIn) * density
}
